(15162, '_transient_code_snippets_welcome_data', 'a:5:{s:6:\"banner\";a:9:{s:3:\"key\";s:6:\"bf2025\";s:14:\"start_datetime\";O:17:\"DateTimeImmutable\":3:{s:4:\"date\";s:26:\"2025-11-18 00:00:00.000000\";s:13:\"timezone_type\";i:3;s:8:\"timezone\";s:3:\"UTC\";}s:12:\"end_datetime\";O:17:\"DateTimeImmutable\":3:{s:4:\"date\";s:26:\"2025-12-03 00:00:00.000000\";s:13:\"timezone_type\";i:3;s:8:\"timezone\";s:3:\"UTC\";}s:9:\"text_free\";s:63:\"Save up to 50% on Code Snippets Pro with our Black Friday Sale!\";s:15:\"action_url_free\";s:45:\"https://codesnippets.pro/pricing/?cs_user=new\";s:17:\"action_label_free\";s:8:\"Get Deal\";s:8:\"text_pro\";s:58:\"Save up to 50% on your upgrade with our Black Friday Sale!\";s:14:\"action_url_pro\";s:50:\"https://codesnippets.pro/pricing/?cs_user=existing\";s:16:\"action_label_pro\";s:8:\"Get Deal\";}s:9:\"hero-item\";a:3:{s:4:\"name\";s:24:\"Meet Snippet Conditions!\";s:10:\"follow_url\";s:78:\"https://codesnippets.pro/blog/version-3-7-snippet-conditions-official-release/\";s:9:\"image_url\";s:78:\"https://codesnippets.pro/wp-content/uploads/2025/09/conditions_screenshot.webp\";}s:8:\"features\";a:4:{i:0;a:5:{s:5:\"title\";s:28:\"Pssss... Get Secret Discount\";s:10:\"follow_url\";s:22:\"https://snipco.de/TFIG\";s:9:\"image_url\";s:81:\"https://codesnippets.pro/wp-content/uploads/2024/09/Promotions_Hero_All_Plans.png\";s:8:\"category\";s:5:\"offer\";s:11:\"description\";s:100:\"Get secret discount on all Code Snippets Pro plans. Just use coupon code \'General5\' at the checkout!\";}i:1;a:5:{s:5:\"title\";s:25:\"Add Unsplash to WordPress\";s:10:\"follow_url\";s:22:\"https://snipco.de/Mind\";s:9:\"image_url\";s:53:\"https://i3.ytimg.com/vi/kRSwWDanX0A/maxresdefault.jpg\";s:8:\"category\";s:3:\"tip\";s:11:\"description\";s:70:\"Code Snippet to Add Unsplash to WordPress - Find and Download Images..\";}i:2;a:5:{s:5:\"title\";s:30:\"Code Snippet Cloud Setup Guide\";s:10:\"follow_url\";s:22:\"https://snipco.de/Mine\";s:9:\"image_url\";s:149:\"https://cdn.getgist.com/attachment_images/76ca6cef08ca8e69ac1e7fbc15004bebbd08ad595ee67e0d7b55d1a9555354bfScreenshot%202023-11-23%20at%2000.50.02.png\";s:8:\"category\";s:5:\"guide\";s:11:\"description\";s:143:\"We have done our best to make the cloud set up as smooth and easy as possible. This guide below will walk you through the process step by step.\";}i:3;a:5:{s:5:\"title\";s:14:\"Cloud and AI +\";s:10:\"follow_url\";s:22:\"https://snipco.de/Minf\";s:9:\"image_url\";s:53:\"https://i3.ytimg.com/vi/rEOC2bIwY-w/maxresdefault.jpg\";s:8:\"category\";s:11:\"new feature\";s:11:\"description\";s:68:\"Code Snippets 3.6 Announcement - AI CodeSnippets - Generate AI Code!\";}}s:8:\"partners\";a:4:{i:0;a:3:{s:5:\"title\";s:9:\"Elementor\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3d\";s:9:\"image_url\";s:76:\"https://codesnippets.pro/wp-content/uploads/2024/05/Elementor-logo-green.png\";}i:1;a:3:{s:5:\"title\";s:7:\"InstaWP\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3n\";s:9:\"image_url\";s:68:\"https://codesnippets.pro/wp-content/uploads/2024/05/instawp-logo.png\";}i:2;a:3:{s:5:\"title\";s:11:\"Dynamic.ooo\";s:10:\"follow_url\";s:28:\"https://snipco.de/dynamicooo\";s:9:\"image_url\";s:71:\"https://codesnippets.pro/wp-content/uploads/2025/09/Dynamicooo-Logo.png\";}i:3;a:3:{s:5:\"title\";s:10:\"Crocoblock\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3l\";s:9:\"image_url\";s:71:\"https://codesnippets.pro/wp-content/uploads/2024/05/crocoblock-logo.png\";}}s:9:\"changelog\";a:4:{s:5:\"3.9.2\";a:2:{s:7:\"Changed\";a:1:{s:4:\"core\";a:6:{i:0;s:85:\"Introduced a custom scissors icon and updated button title for the TinyMCE extension.\";i:1;s:50:\"Improved back-navigation styling on the edit page.\";i:2;s:78:\"Refined layout for column names and action buttons in the Cloud Snippets list.\";i:3;s:56:\"Enhanced overall styling of cloud-related UI components.\";i:4;s:76:\"Optimized cloud search with more efficient pagination and snippet retrieval.\";i:5;s:83:\"Introduced groundwork to prevent Composer dependency collisions with other plugins.\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:2:{i:0;s:80:\"Improved sanitization and normalization across Cloud API and pagination outputs.\";i:1;s:72:\"Resolved various TinyMCE issues reported in the WordPress support forum.\";}}}s:5:\"3.9.1\";a:2:{s:7:\"Changed\";a:1:{s:4:\"core\";a:2:{i:0;s:98:\"Migrated to native CSS direction handling (RTL/LTR) for improved compatibility and simpler styling\";i:1;s:54:\"Updated dependencies to the latest compatible versions\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:2:{i:0;s:72:\"Fixed TinyMCE menu button registration to prevent initialization failure\";i:1;s:64:\"Fixed the position of the \'code direction\' control in the editor\";}}}s:5:\"3.9.0\";a:3:{s:5:\"Added\";a:1:{s:4:\"core\";a:2:{i:0;s:100:\"Added contextual notices in the Snippets list table to surface action results and warnings in the UI\";i:1;s:89:\"Expanded Multisite Sharing settings for clearer control over network-wide snippet sharing\";}}s:7:\"Changed\";a:1:{s:4:\"core\";a:1:{i:0;s:147:\"Modernized browser support targets and polished admin UI (clearer row-action badges, improved Pro badge hover, refined active snippet name styling)\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:2:{i:0;s:67:\"Fixed REST API pagination to return correct results and page counts\";i:1;s:72:\"Resolved styling selector so the active snippet name highlights reliably\";}}}s:12:\"3.9.0-beta.2\";a:3:{s:5:\"Added\";a:1:{s:4:\"core\";a:2:{i:0;s:54:\"Added \'Snippets\' row action to the Network Sites table\";i:1;s:50:\"Improved snippet name visibility for network users\";}}s:7:\"Changed\";a:1:{s:4:\"core\";a:2:{i:0;s:66:\"Refined badge styling and hover effects for row actions and badges\";i:1;s:83:\"Impoved icon style and color usage for network snippets for clearer differentiation\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:4:{i:0;s:79:\"Improved network snippets management with better subsite menu permission checks\";i:1;s:47:\"Fixed status labels for shared network snippets\";i:2;s:70:\"Corrected network condition checks and improved snippet fetching logic\";i:3;s:62:\"Handled fatal errors in file-based snippets to prevent crashes\";}}}}}', 'off'),
