(241, 1, '2025-07-06 15:05:14', '2025-07-06 18:05:14', '/*\n * módulo de autor na home:start\n */\n\n.authors-home .pp-multiple-authors-wrapper.ppma_boxes_139 ul, .pp-multiple-authors-index .author-index-authors ul {\n	display: flex;\n	flex-wrap: initial;\n	overflow-x: auto;\n	white-space: nowrap;\n}\n\n.authors-home .pp-multiple-authors-boxes-wrapper.pp-multiple-authors-layout-centered.multiple-authors-target-widget .pp-multiple-authors-boxes-li {\n	width:150px;\n}\n\n.authors-home .pp-multiple-authors-layout-centered ul li {\n	padding-bottom:0;\n	min-height:auto;\n	margin-bottom:0;\n}\n\n.authors-home .pp-multiple-authors-boxes-wrapper.pp-multiple-authors-layout-centered.multiple-authors-target-widget .pp-author-boxes-avatar img {\n	width:100px!important;\n	height:100px!important;\n}\n\n.authors-home .pp-multiple-authors-boxes-wrapper.pp-multiple-authors-layout-centered.multiple-authors-target-widget .pp-multiple-authors-boxes-li {\n	border-width: 0!important;\n}\n\n.authors-home .pp-multiple-authors-layout-centered .multiple-authors-name a {\n	text-decoration: none;\n}\n\n.authors-home [class*=\"ppma-author-field-type\"], .authors-home .pp-author-boxes-description, .authors-home .widget-title\n{\n	display:none;\n}\n/*\n * módulo de autor na home:start\n */\n\n/*\n * Post CSS: start\n */\n.ast-separate-container .ast-single-related-posts-container {\n	border-top:1px solid var(--ast-global-color-3);\n}\n\n.post-navigation {\n	display:none;\n}\n/*\n * Post CSS: end\n */\n\n.cnt-image {\n	display:block;\n	margin:0 auto;\n	width:150px;\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '170-revision-v1', '', '', '2025-07-06 15:05:14', '2025-07-06 18:05:14', '', 170, 'https://alura.test/?p=241', 0, 'revision', '', 0),
